/** DSTU 4145-2002 parameters (short, for point uncompression) */
export interface DSTUShortParameters {
    /** Param `a` */
    a: 0 | 1;
    /** Param `b` */
    b: string;
    /** Field size */
    m: number;
    /** Polynomial coefficients */
    ks: number[];
    /** Parameters for Optimal normal basis (ONB) */
    onb?: {
        /** Compressed matrix for ONB multiplication */
        matrix: string;
        /** Roots in ONB for PB-irreducible */
        root1: string;
        /** Roots in PB for ONB-irreducible */
        root2: string;
    }
}

/** DSTU 4145-2002 curve parameters */
export interface DSTUParameters extends DSTUShortParameters {
    /** Curve order */
    order: string;
    /** Curve cofactor */
    cofactor: 2 | 4;
    /** Base point `X` coordinate */
    Gx: string;
    /** Base point `Y` coordinate */
    Gy: string;
}

